        var s = ell.apply(null, P(1.85, 1.9, 0).concat([31, 11, "#1B2A3A", 0, .1])), xa = .3, xb = 3.3, yc = 1.75, zt = 3.75, wh = "#FFFDF6", wd = { top: wh, left: "#F6ECE0", right: "#DCCEBE" };
